class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def mergeInBetween(list1: ListNode, a: int, b: int, list2: ListNode) -> ListNode:
    # 1. Find node before the aᵗʰ node
    prev_a = list1
    if a == 0:
        prev_a = None
    else:
        for _ in range(a - 1):
            prev_a = prev_a.next
    # 2. Find node after the bᵗʰ node
    curr = list1 if prev_a is None else prev_a.next
    for _ in range(b - a + 1):
        curr = curr.next
    after_b = curr
    # 3. Connect prev_a to list2 head; or set head = list2 if a == 0
    if prev_a:
        prev_a.next = list2
        head = list1
    else:
        head = list2
    # 4. Go to tail of list2
    tail2 = list2
    while tail2.next:
        tail2 = tail2.next
    # 5. Connect tail2 to after_b
    tail2.next = after_b
    return head
